final class ActionGuardTest {static int n;static void yes(boolean b,String s){if(!b)throw new AssertionError(s);n++;}public static void main(String[] args){for(String label:new String[]{"确定，需支付5.90元","支付立减","确认支付","去付款","实付款¥4.99","提交订单","确认并支付"})yes(ActionGuard.finalAction(label),"Financial meaning escaped boundary");for(String label:new String[]{"200+人付款","3.2万人已付款","搜索商品","立即购买","选择规格","销量2000"})yes(!ActionGuard.finalAction(label),"Sales evidence or navigation treated as payment");yes(!ActionGuard.requiresHandoff("百洁布 3.2万人已付款",true),"Sales evidence blocked product");yes(ActionGuard.requiresHandoff("确定，需支付5.90元",true),"Payment label escaped node check");yes(ActionGuard.requiresHandoff("立即购买",false),"Checkout scope bypassed");yes(!ActionGuard.requiresHandoff("立即购买",true),"Authorized purchase navigation blocked");yes(ActionGuard.unlabelledCheckoutBottom(true,true,false,916),"Unlabelled bottom checkout tap escaped");yes(!ActionGuard.unlabelledCheckoutBottom(true,true,false,500),"Product visual selection blocked");yes(!ActionGuard.unlabelledCheckoutBottom(true,true,true,916),"Stable node route blocked");yes(!ActionGuard.unlabelledCheckoutBottom(false,true,false,916),"Non-checkout task altered");yes(!ActionGuard.unlabelledCheckoutBottom(true,false,false,916),"Non-merchant task altered");System.out.println("PASS: "+n+" financial meaning and sales-counter boundaries");}}
